mapper.select:
select b.id, b.user_id, b.role_type, b.role_name, b.record, b.record_time, b.avatar, b.enter_time, a.round, a.process_id from t_chat_history a join t_chat_history_detail b on a.id = b.chat_history_id and b.is_deleted = 0 where a.is_deleted = 0 and a.element_id = #{elementId}
and a.process_id = #{processId}
and a.round = #{round}
order by b.create_date,b.id
